<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>神豪终端</title><style>/* rc.40 统一星愿卡面样式（由 build.mjs 同步注入 phone.html 与 wheel.html） */
.wc-card{
  position:relative;
