}
.wc-face::after{
  content:"";
  position:absolute;
  inset:-40%;
  pointer-events:none;
  z-index:3;
  background:linear-gradient(125deg,transparent 38%,var(--wc-sheen,rgba(255,255,255,.2)) 50%,transparent 62%);
  animation:wcCardSheen var(--wc-dur,4.4s) linear infinite;
}
@keyframes wcCardSheen{
  0%{transform:translateX(-65%) rotate(12deg)}
  100%{transform:translateX(65%) rotate(12deg)}
