.wc-card[data-wc-size="md"]{--wc-radius:11px;--wc-pad:7px;--wc-inset:3.5px;--wc-fs-top:8px;--wc-fs-name:10px;--wc-fs-val:13px;--wc-foot-pad:3.5px 3px}
.wc-card[data-wc-size="sm"]{--wc-radius:10px;--wc-pad:5px;--wc-inset:3px;--wc-fs-top:7.5px;--wc-fs-name:9px;--wc-fs-val:11.5px;--wc-foot-pad:3px 2px}
