/* 左侧 48×48 旋转小轮盘徽章 */
.mini-wheel-anchor{
  width:46px;height:46px;flex-shrink:0;position:relative;
  display:grid;place-items:center;border-radius:50%;
  box-shadow:0 0 0 1px var(--we-border),0 0 14px var(--we-glow);
  background:radial-gradient(circle,#2f2436 0%,#14101a 100%);
  will-change:transform;
}
.mini-wheel-anchor svg{width:44px;height:44px;display:block;animation:miniSpinCCW 28s linear infinite}
.mini-wheel-anchor.is-cw svg{animation:miniSpinCW 32s linear infinite}
.mini-wheel-anchor.is-fast svg{animation:miniSpinCCW 24s linear infinite}
@keyframes miniSpinCCW{to{transform:rotate(-360deg)}}
@keyframes miniSpinCW{to{transform:rotate(360deg)}}
.mini-wheel-anchor.bounce{animation:miniBounce .36s cubic-bezier(.22,1.4,.36,1)}
@keyframes miniBounce{0%{transform:scale(1)}30%{transform:scale(1.18)}62%{transform:scale(.94)}82%{transform:scale(1.05)}100%{transform:scale(1)}}

.wcard-b-copy{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}
.wcard-b-top{display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.wcard-b-top b{font:700 calc(13.5px * var(--cj-font-scale,1))/1.2 "Songti SC","SimSun",Georgia,serif;letter-spacing:.1em;color:#fff0c4}
.wcard-b-badge{flex:0 0 auto;font-size:calc(9.5px * var(--cj-font-scale,1));padding:2px 7px;border-radius:999px;background:var(--we-badge-bg);color:var(--we-badge-fg);border:1px solid var(--we-badge-bd);font-weight:700;white-space:nowrap}
.wcard-b-meta{font-size:calc(10px * var(--cj-font-scale,1));color:#c9bfa9;line-height:1.45}
.wcard-b-arrow{font-size:18px;color:var(--we-badge-fg,#e7c682);flex-shrink:0;padding-right:1px}

/* ===== 画质档位自动降级（挂载在 html[data-wfxq]，联动 prefs.wheelFxQuality） ===== */
:root[data-wfxq="medium"] .mini-wheel-anchor svg{animation:none;transition:transform .45s ease}
:root[data-wfxq="medium"] .wcard-b:hover .mini-wheel-anchor svg{transform:rotate(36deg)}
:root[data-wfxq="medium"] .wcard-b{box-shadow:0 6px 16px rgba(12,8,18,.24),inset 0 1px 0 rgba(255,242,204,.16)}
:root[data-wfxq="medium"] .mini-wheel-anchor{box-shadow:0 0 0 1px var(--we-border)}

:root[data-wfxq="low"] .wcard-b{background:var(--we-bg-flat);box-shadow:none;transition:none}
:root[data-wfxq="low"] .wcard-b::after{display:none}
:root[data-wfxq="low"] .mini-wheel-anchor{box-shadow:none}
:root[data-wfxq="low"] .mini-wheel-anchor svg{animation:none}

@media(prefers-reduced-motion:reduce){
  .mini-wheel-anchor svg,.mini-wheel-anchor.bounce{animation:none!important}
  .wcard-b::after{display:none}
}
.dock-list{display:flex;flex-direction:column;gap:8px;margin-bottom:10px}
@media(min-width:600px){.phone.is-bottom-dock .dock-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr))}}
.dock-row{display:flex;align-items:center;gap:11px;width:100%;padding:11px 12px;border-radius:14px;border:1px solid var(--ui-line);background:var(--ui-card);color:var(--ui-ink);text-align:left;cursor:pointer;transition:border-color .16s,background .16s}
.dock-row:hover{border-color:var(--ui-accent);background:var(--ui-soft)}
.dock-icon{width:36px;height:36px;border-radius:11px;background:var(--ui-soft);display:grid;place-items:center;font-size:calc(16px * var(--cj-font-scale,1));flex-shrink:0}
.dock-copy{flex:1;min-width:0}
.dock-copy b{display:block;font-size:calc(13px * var(--cj-font-scale,1));line-height:1.25}
.dock-copy small{display:block;font-size:calc(10px * var(--cj-font-scale,1));color:var(--ui-sub);margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dock-tail{display:flex;align-items:center;gap:5px;flex-shrink:0;font-size:calc(11px * var(--cj-font-scale,1));font-weight:700}
.dock-tail i{font-style:normal;font-size:calc(15px * var(--cj-font-scale,1));color:var(--ui-sub)}

/* ===== rc.39 追加：TOY·LINK 常驻卡四态 ===== */
.toylink-card{position:relative;display:flex;align-items:center;gap:10px;padding:12px 12px 12px 15px;margin-top:10px;border-radius:14px;border:1px solid var(--ui-line);background:var(--ui-card);--tl-bar:var(--ui-line);transition:border-color .18s,opacity .18s}
.toylink-card::before{content:"";position:absolute;left:0;top:11px;bottom:11px;width:3.5px;border-radius:3px;background:var(--tl-bar)}
.toylink-ico{width:36px;height:36px;border-radius:11px;background:var(--ui-soft);display:grid;place-items:center;font-size:calc(15px * var(--cj-font-scale,1));flex-shrink:0}
.toylink-body{flex:1;min-width:0}
.toylink-body b{display:block;font-size:calc(12.5px * var(--cj-font-scale,1));line-height:1.25}
.toylink-body small{display:block;font-size:calc(10px * var(--cj-font-scale,1));color:var(--ui-sub);margin-top:2px;line-height:1.4}
.toylink-card .cj-act{flex-shrink:0;display:inline-flex;align-items:center;gap:5px}
.toylink-card[data-toylink-state="locked"]{border-style:dashed;opacity:.76;--tl-bar:#9aa3b5}
.toylink-card[data-toylink-state="locked"] .toylink-ico{filter:grayscale(.6)}
