/* ===== rc.40 四档叠卡卡册 + 卡面右下角 ⚙ 设置按钮 ===== */
.binder-decks{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;padding:2px}
.binder-stack{min-width:0}
.binder-stack.is-expanded{grid-column:1 / -1;animation:binderPop .2s cubic-bezier(.2,.8,.2,1)}
@keyframes binderPop{from{opacity:.4;transform:scale(.96) translateY(-4px)}to{opacity:1;transform:scale(1) translateY(0)}}
.stack-open-bar{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:8px}
.stack-badge{font-size:calc(11px * var(--cj-font-scale,1));font-weight:700;padding:2px 9px;border-radius:999px;border:1px solid var(--ui-line);background:var(--ui-soft,var(--ui-card2));color:var(--ui-ink)}
.stack-deck{position:relative;display:block;width:100%;padding:0;border:0;background:transparent;cursor:pointer;text-align:left}
