.stack-layer.layer-1{transform:translate(4px,-4px) rotate(2.5deg);opacity:.72}
.stack-layer.layer-2{transform:translate(8px,-8px) rotate(5deg);opacity:.44}
.stack-front{position:relative;z-index:2;display:block}
.stack-count{position:absolute;right:6px;top:6px;z-index:4;padding:1px 7px;border-radius:999px;font:700 calc(10px * var(--cj-font-scale,1))/1.3 Georgia,serif;background:rgba(16,14,22,.78);border:1px solid rgba(246,227,176,.5);color:#f6e3b0}
.stack-flags{position:absolute;right:6px;bottom:6px;z-index:4;display:flex;gap:3px;font-size:calc(9px * var(--cj-font-scale,1));padding:1px 5px;border-radius:999px;background:rgba(0,0,0,.42);color:#ffe3a8}
.stack-deck:hover .stack-front{transform:translateY(-2px);transition:transform .16s ease}
.binder-item{position:relative}
