.wc-gear:hover{background:rgba(48,38,30,.92)}
.card-menu-meta{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:9px 11px;margin-bottom:10px;border-radius:11px;background:var(--ui-card2);border:1px solid var(--ui-line)}
.card-menu-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
