.cache-warn .cj-act{flex-shrink:0;font-size:calc(10px * var(--cj-font-scale,1));padding:4px 9px}


/* rc.41：TOY·LINK 未解锁预览（只读锁定态） */
.tl-preview-badge{display:inline-block;font:700 10px/1.4 sans-serif;padding:2px 8px;border-radius:999px;border:1px solid var(--ui-line,#d9e3d8);background:var(--ui-soft,#f2f5f0);color:var(--ui-accent,#557a64);letter-spacing:.4px}
