.tl-preview-modes{display:flex;gap:6px;flex-wrap:wrap}
.tl-preview-modes span{padding:3px 9px;border-radius:999px;border:1px solid var(--ui-line,#d9e3d8);background:var(--ui-soft,#f2f5f0);font-size:calc(10px * var(--cj-font-scale,1))}
