.pending-ops-bar{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:0 0 8px;padding:7px 10px;border-radius:12px;border:1px solid rgba(185,140,64,.35);background:linear-gradient(180deg,rgba(255,247,232,.96),rgba(250,239,219,.96));font-size:calc(11px * var(--cj-font-scale,1));color:#6b4a1c}
