.pending-ops-bar .pob-undo:hover{background:#a26d1f}
.pending-ops-bar .pob-sep{color:rgba(107,74,28,.45)}

/* ===== rc.47 工坊高定 · choker（整段搬运自 RC47总方案/03_原型/rc47-proto-choker.html） ===== */
.workshop-page.is-choker{
  --cj-font-scale:1;
  /* 原型画布背景（不进卡） */
  --proto-bg:radial-gradient(880px 520px at 50% 0%,rgba(166,42,66,.20),transparent 65%),#09070a;
  /* 项圈工坊 · 黑曜皮革与冷金工艺坊专属色板 */
  --chk-bg:#100c11;
  --chk-card:#1a131a;
  --chk-card-hi:#241a23;
  --chk-well:#130e14;
  --chk-ink:#f5ecec;
  --chk-sub:#b8a3a8;
  --chk-muted:#857077;
  --chk-line:rgba(226,184,190,.16);
  --chk-line-hi:rgba(228,104,126,.48);
  --chk-crimson:#cc3b58;
  --chk-crimson-hi:#f27e96;
  --chk-crimson-soft:rgba(204,59,88,.16);
  --chk-crimson-bd:rgba(232,102,128,.46);
  --chk-brass:#d8b377;
  --chk-brass-soft:rgba(216,179,119,.14);
  --chk-brass-bd:rgba(216,179,119,.44);
  --chk-danger:#f06d7d;
  --chk-danger-bg:rgba(218,74,94,.14);
  --chk-danger-bd:rgba(240,109,125,.42);
  --chk-frame:#241920;
  --chk-shadow:rgba(3,1,6,.66);
}
.workshop-page.is-choker *{box-sizing:border-box}
.workshop-page.is-choker button,.workshop-page.is-choker input{font:inherit}
.workshop-page.is-choker button{cursor:pointer}
.workshop-page.is-choker button:disabled{cursor:not-allowed;opacity:.5}
.workshop-page.is-choker button:focus-visible,.workshop-page.is-choker input:focus-visible{outline:2px solid var(--chk-crimson-hi);outline-offset:2px}
.workshop-page.is-choker /* ===== 原型演示条（仅预览用，不进卡） ===== */ .proto-note{font-size:11px;color:var(--chk-sub);letter-spacing:.08em;
  padding:4px 14px;border-radius:999px;background:var(--chk-card);border:1px solid var(--chk-line);}
.workshop-page.is-choker .pbtn{border:1px solid var(--chk-line);background:var(--chk-well);color:var(--chk-sub);
  border-radius:8px;padding:4px 9px;font-size:11px;transition:border-color .16s,color .16s,background .16s;}
.workshop-page.is-choker .pbtn:hover{border-color:var(--chk-line-hi);color:var(--chk-ink)}
.workshop-page.is-choker .pbtn.on{background:var(--chk-crimson);color:#fff;border-color:var(--chk-crimson);font-weight:700}
.workshop-page.is-choker /* ===== 手机壳 ===== */ .phone{position:relative;width:375px;max-width:100%;height:812px;
  border-radius:40px;background:var(--chk-bg);border:7px solid var(--chk-frame);
  box-shadow:0 28px 72px var(--chk-shadow),inset 0 0 0 1px rgba(255,224,228,.12);
  overflow:hidden;display:flex;flex-direction:column;
  transition:width .22s ease,border-radius .22s ease;}
.workshop-page.is-choker{flex:1;min-height:0;display:flex;flex-direction:column;
  color:var(--chk-ink);
  animation:chkwsEnter .24s cubic-bezier(.22,1,.36,1) both;}
@keyframes chkwsEnter{from{opacity:0;transform:translateY(10px) scale(.985)}to{opacity:1;transform:none}}
.workshop-page.is-choker .ws-scroll{flex:1;min-height:0;overflow-y:auto;overflow-x:hidden;
  padding:9px 11px 14px;display:flex;flex-direction:column;gap:9px;
  scrollbar-width:thin;scrollbar-color:rgba(226,184,190,.24) transparent;}
.workshop-page.is-choker /* 顶栏 */ .ws-topbar{min-height:34px;display:flex;align-items:center;justify-content:space-between;gap:8px}
.workshop-page.is-choker .backlink{border:1px solid var(--chk-line);background:rgba(255,255,255,.03);color:var(--chk-ink);
  border-radius:999px;padding:4px 11px;font-size:calc(11.5px * var(--cj-font-scale,1));
  font-weight:700;min-height:30px;flex-shrink:0;transition:border-color .16s,background .16s;}
.workshop-page.is-choker .backlink:hover{border-color:var(--chk-line-hi);background:var(--chk-crimson-soft)}
.workshop-page.is-choker .ws-topbar-right{display:flex;align-items:center;gap:6px;min-width:0}
.workshop-page.is-choker .ws-status-pill{font-size:calc(10.5px * var(--cj-font-scale,1));font-weight:700;padding:4px 10px;border-radius:999px;
  background:var(--chk-card);color:var(--chk-sub);border:1px solid var(--chk-line);
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:176px;}
.workshop-page.is-choker .ws-status-pill.worn{background:var(--chk-crimson-soft);color:#ffc4d0;border-color:var(--chk-crimson-bd)}
