.phone .tag.dev-choker{background:#fdf3df;color:#7a4b12;border:1px solid #e2c086}
.theme-purple .phone .tag.dev-choker{background:#473522;color:#ffd596;border:1px solid #785937}
.phone .tag.dev-imprint{background:#ffeef3;color:#a32d56;border:1px solid #ebaec2}
