  display: flex;
  gap: 6px;
  margin: 6px 0 4px;
}
.workshop-page.is-toylink .tl-tac-btn {
  flex: 1;
  height: 30px;
  border-radius: 7px;
  font-size: 11px;
  font-weight: 800;
  border: 1px solid rgba(226, 184, 255, 0.28);
  background: rgba(45, 27, 62, 0.85);
  color: #ebd6ff;
